fn stream(input: &[u8], opts: DecodeOptions) -> Result<Vec<u8>, Error> {
    let mut d = Decoder::new(opts);
    let mut out = Vec::new();
    let mut buf = [0u8; 64];
    let mut pos = 0;
    loop {
        let p = d.decode(&input[pos..], &mut buf, true)?;
        pos += p.consumed;
        out.extend_from_slice(&buf[..p.produced]);
        if p.status == Status::Done {
            return Ok(out);
